var i=`0006-varenyky-with-potatoes`;var n=`world-0006`;var o=`UA`;var a=`eastern-europe`;var l=4;var s=79;var g={en:`Varenyky with Potatoes`,ua:`Вареники з картоплею`};var r={en:`A classic dish from Ukraine, featuring chicken egg, potato, yellow onion, sour cream. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: куряче яйце, картопля, жовта цибуля, сметана. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,500,`g`],[`water`,230,`ml`],[`chicken-egg`,1,`pcs`],[`table-salt`,3,`g`]]},{en:`Boil the potatoes until soft, mash; sauté the diced onion in butter and fold into the potatoes. Cool fully before filling.`,ua:`Зваріть картоплю до м’якості, розімніть; нарізану цибулю підсмажте на маслі та змішайте з картоплею. Повністю остудіть начинку.`,t:[`chopping`,`mixing`],m:22,i:[[`potato`,600,`g`],[`yellow-onion`,150,`g`],[`unsalted-butter`,35,`g`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:25,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 5 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 5 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:5,i:[[`water`,1500,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sour-cream`,100,`g`],[`dill`,10,`g`]]}];var h={slug:i,id:n,country:`UA`,region:a,servings:4,minutes:79,title:g,text:r,steps:u};export{o as country,h as default,n as id,s as minutes,a as region,l as servings,i as slug,u as steps,r as text,g as title};